import React, { useContext, useState, useEffect } from 'react';
import { AppContext } from './AppContext';

export default function SettingsPanel() {
  const { user, theme, setTheme, language, setLanguage, token, setUser } = useContext(AppContext);

  const [name, setName] = useState(user?.name || '');
  const [email, setEmail] = useState(user?.email || '');
  const [age, setAge] = useState(user?.age || '');
  const [gender, setGender] = useState(user?.gender || '');
  const [message, setMessage] = useState(null);

  useEffect(() => {
    setName(user?.name || '');
    setEmail(user?.email || '');
    setAge(user?.age || '');
    setGender(user?.gender || '');
  }, [user]);

  const toggleTheme = () => {
    setTheme(theme === 'dark' ? 'light' : 'dark');
  };

  const handleLanguageChange = (e) => {
    setLanguage(e.target.value);
  };

  const handleSave = async () => {
    setMessage(null);
    try {
      const res = await fetch('/user/update', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ name, age, gender }),
      });
      if (!res.ok) throw new Error('Update failed');
      const updatedUser = await res.json();
      setUser(updatedUser);
      setMessage('User info updated!');
    } catch (e) {
      setMessage('Update failed.');
    }
  };

  return (
    <div className={`settings-panel ${theme === 'dark' ? 'dark' : ''}`}>
      {/* User header with avatar and main info */}
      <div className="user-header" style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1.5rem' }}>
        <img
          src={`https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=random&size=128`}
          alt="User Avatar"
          className="avatar"
          style={{ borderRadius: '50%', width: '80px', height: '80px' }}
        />
        <div>
          <h1 style={{ margin: 0 }}>{name || 'User'}</h1>
          <p style={{ margin: 0, color: '#555' }}>{email || 'No email'}</p>
          <p style={{ margin: 0, color: '#888', fontSize: '0.9rem' }}>ID: {user?.id || 'N/A'}</p>
        </div>
      </div>

      {/* Editable settings */}
      <div className="setting-group">
        <label>Name</label>
        <input value={name} onChange={e => setName(e.target.value)} />
      </div>

      <div className="setting-group">
        <label>Age</label>
        <input
          type="number"
          min="1"
          max="120"
          value={age}
          onChange={e => setAge(e.target.value)}
        />
      </div>

      <div className="setting-group">
        <label>Gender</label>
        <select value={gender} onChange={e => setGender(e.target.value)}>
          <option value="">Select gender</option>
          <option value="male">Male</option>
          <option value="female">Female</option>
          <option value="other">Other</option>
        </select>
      </div>

      <div className="setting-group">
        <label>Theme</label>
        <button onClick={toggleTheme}>
          Switch to {theme === 'dark' ? 'Light' : 'Dark'} Mode
        </button>
      </div>

      <div className="setting-group">
        <label>Language</label>
        <select value={language} onChange={handleLanguageChange}>
          <option value="en">English</option>
          <option value="fr">French</option>
          <option value="ar">Arabic</option>
        </select>
      </div>

      <button onClick={handleSave} style={{ marginTop: '1rem' }}>Save Settings</button>

      {message && <p style={{ marginTop: '1rem', color: message.includes('failed') ? 'red' : 'green' }}>{message}</p>}
    </div>
  );
}
